// Every derivation against the contracts' golden vectors (test/vectors/ids.json, generated by viem in contracts and
// checked by Foundry against Keys.sol). Two languages, one answer.
import { describe, expect, it } from "vitest";
import type { Hex, PrincipalId } from "../src/core/hex.ts";
import { KEY_VECTORS } from "../src/generated/domains.ts";
import * as keys from "../src/protocol/keys.ts";

const i = KEY_VECTORS.inputs;
const o = KEY_VECTORS.outputs;
const lc = (h: string) => h.toLowerCase();

describe("Keys twin", () => {
  it("principals", () => {
    expect(keys.keyPrincipal(i.eoa as Hex)).toBe(lc(o.eoaPrincipal));
    expect(lc(keys.contractPrincipal(i.realmOrigin as Hex, i.contractAddress as Hex))).toBe(
      lc(o.contractPrincipal),
    );
  });
  it("types and records", () => {
    expect(lc(keys.typeId(i.shape as Hex, i.refTypes as readonly Hex[], i.ruleId as Hex))).toBe(
      lc(o.typeId),
    );
    expect(lc(keys.typeId(i.shape as Hex, [], i.ruleId as Hex))).toBe(lc(o.typeIdNoRefs));
    expect(lc(keys.recordId(o.typeId as Hex, i.body as Hex))).toBe(lc(o.recordId));
    expect(lc(keys.recordFromHash(o.typeId as Hex, i.bodyHash as Hex))).toBe(lc(o.recordFromHash));
  });
  it("subjects, positions, bindings, scopes", () => {
    const p = o.eoaPrincipal as PrincipalId;
    expect(lc(keys.subjectId(p, i.salt as Hex))).toBe(lc(o.subjectId));
    const subject = o.subjectId as Hex;
    expect(lc(keys.positionKey(i.purpose as Hex, subject, i.role as Hex))).toBe(lc(o.positionKey));
    expect(lc(keys.bindingKey(p, o.positionKey as Hex))).toBe(lc(o.bindingKey));
    expect(lc(keys.scopeKey(p, i.purpose as Hex, subject))).toBe(lc(o.scopeKey));
    expect(lc(keys.roleScopeKey(p, i.purpose as Hex, i.role as Hex))).toBe(lc(o.roleScopeKey));
  });
  it("realm, publication, role key, shape", () => {
    const origin = keys.realmOrigin(11155111n, i.contractAddress as Hex, i.salt as Hex);
    expect(lc(origin)).toBe(lc(o.realmOrigin));
    expect(lc(keys.realmId(origin, 1))).toBe(lc(o.realmId));
    expect(lc(keys.contractPrincipal(origin, i.contractAddress as Hex))).toBe(
      lc(o.contractPrincipalOfOrigin),
    );
    expect(lc(keys.publicationId(o.eoaPrincipal as PrincipalId, i.bodyHash as Hex))).toBe(
      lc(o.publicationId),
    );
    expect(lc(keys.roleKey(i.purpose as Hex, i.role as Hex))).toBe(lc(o.roleKey));
    expect(lc(keys.shape(i.body as Hex))).toBe(lc(o.shape));
  });
  it("posting lists", () => {
    const t = o.typeId as Hex;
    const r = o.recordId as Hex;
    expect(lc(keys.lists.byType(t))).toBe(lc(o.byTypeList));
    expect(lc(keys.lists.byAuthor(o.eoaPrincipal as PrincipalId))).toBe(lc(o.byAuthorList));
    expect(lc(keys.lists.backlink(r))).toBe(lc(o.backlinkList));
    expect(lc(keys.lists.history(o.bindingKey as Hex))).toBe(lc(o.historyList));
    expect(lc(keys.lists.scope(o.scopeKey as Hex))).toBe(lc(o.scopeList));
    expect(lc(keys.lists.reference(t, i.ordinal, r))).toBe(lc(o.referenceList));
    expect(lc(keys.lists.byRecord(r))).toBe(lc(o.byRecordList));
    expect(lc(keys.lists.uniqueByType(t))).toBe(lc(o.uniqueByTypeList));
    expect(lc(keys.lists.scalar(t, i.spec, i.scalarKind, i.value as Hex))).toBe(lc(o.scalarList));
    expect(lc(keys.lists.digest(i.algorithm as Hex, i.value as Hex))).toBe(lc(o.digestList));
  });
});
